<?php
if(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)==='/api/count'){$p=getenv('PODS_APP_DATA').'/count';$f=fopen($p,'c+');flock($f,LOCK_EX);$n=(int)stream_get_contents($f);if($_SERVER['REQUEST_METHOD']==='POST'){$n++;rewind($f);ftruncate($f,0);fwrite($f,(string)$n);}flock($f,LOCK_UN);fclose($f);header('Content-Type: application/json');echo json_encode(['count'=>$n]);}else{header('Content-Type: text/html');echo '<!doctype html><html><title>PHP counter</title><h1>PHP counter</h1><p id="value"></p><button id="add">Add one</button><script>async function refresh(){document.querySelector("#value").textContent=(await(await fetch("/api/count")).json()).count}document.querySelector("#add").onclick=async()=>{await fetch("/api/count",{method:"POST"});refresh()};refresh()</script></html>';}